package reference;

import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;

import reference.Calculator.Context;
import reference.Purchase.Customer;
import reference.Purchase.Item;
import reference.Result.Refusal;
import reference.Result.Summary;

/**
 * The prompt's examples ("Exemplos conferidos pelo financeiro"), generated BY THE CALCULATOR: the number
 * written in the prompt is, by construction, what the reference calculates. The examples are neutral (they
 * do not say which rule they exercise). The generated text is Portuguese, because the prompt is Portuguese.
 *
 * What each one covers (only here, never in the prompt):
 *   1  WELCOME10 on the first purchase + Pix with a coupon (no discount) + NORTH (extra days, 2.5% insurance)
 *   2  V5's example 2, with the TransLog instead of the formula: credit card 6x with interest, SILVER, MIDWEST
 *   3  GOLD with the courier (pays shipping) + MINUS50 + bank slip + NORTHEAST (courier without extra days)
 *   4  V5's example 4: BUY3PAY2 with 7 socks (below the cap), store pickup, credit card 3x
 *   5  BUY3PAY2 above the 30% cap + Pix with a coupon
 *   6  FREESHIPPING above the 30% cap (expensive shipping, cheap product) + 150 hours = 7 days + bank slip
 *   7  GOLD with express (zero shipping) + insurance at the NORTH limit + gift + Pix without a coupon
 *   8  refusal: FREESHIPPING with store pickup
 *   9  refusal: WELCOME10 from a customer who already has a paid order
 *  10  refusal: a ZIP code the TransLog does not serve
 *
 * Usage: java -cp target/classes reference.PromptExamples                 (prints the section)
 *        java -cp target/classes reference.PromptExamples --check P.md    (checks the prompt P.md: its section
 *        must be identical to the one the reference generates; exits with 1 otherwise)
 */
public final class PromptExamples {

    public record Example(List<Item> items, String shippingMethod, TransLog.Answer transLogAnswer, String coupon,
                   boolean customerHasPaidOrder, String paymentMethod, Integer installments, String clubTier, String region) {}

    public static final String ZIP_CODE = "01310100";
    static final String SECTION_TITLE = "### Exemplos conferidos pelo financeiro";

    public static final List<Example> EXAMPLES = List.of(
            new Example(items("CAM-001", 2, "TEN-001", 1), "EXPRESS", quote(3310, 41), "WELCOME10", false, "PIX", null, "BRONZE", "NORTH"),
            new Example(items("CAM-001", 2, "TEN-001", 1), "ECONOMY", quote(1560, 168), null, false, "CREDIT_CARD", 6, "SILVER", "MIDWEST"),
            new Example(items("FON-001", 2), "COURIER", null, "MINUS50", false, "BANK_SLIP", null, "GOLD", "NORTHEAST"),
            new Example(items("MEI-001", 7, "CAM-001", 2), "STORE_PICKUP", null, "BUY3PAY2", false, "CREDIT_CARD", 3, "SILVER", "SOUTH"),
            new Example(items("CAM-001", 3), "EXPRESS", quote(2475, 30), "BUY3PAY2", false, "PIX", null, "BRONZE", "SOUTHEAST"),
            new Example(items("MEI-001", 1), "ECONOMY", quote(2210, 150), "FREESHIPPING", false, "BANK_SLIP", null, "BRONZE", "SOUTH"),
            new Example(items("JAQ-001", 3, "TEN-001", 1), "EXPRESS", quote(5080, 49), null, false, "PIX", null, "GOLD", "NORTH"),
            new Example(items("CAM-001", 1), "STORE_PICKUP", null, "FREESHIPPING", false, "PIX", null, "SILVER", "SOUTHEAST"),
            new Example(items("CAM-001", 2), "EXPRESS", quote(2900, 36), "WELCOME10", true, "CREDIT_CARD", 2, "BRONZE", "SOUTH"),
            new Example(items("TEN-001", 1), "ECONOMY", new TransLog.ZipNotServed(), null, false, "PIX", null, "BRONZE", "NORTH"));

    public static void main(String[] args) throws Exception {
        String generated = section();
        if (args.length == 2 && args[0].equals("--check")) {
            boolean same = sectionInPrompt(Path.of(args[1])).equals(generated.strip());
            long values = java.util.regex.Pattern.compile("\\d+,\\d{2}").matcher(generated).results().count();
            System.out.println(same ? "the prompt's examples match the reference (" + values + " money values)"
                                    : "THE PROMPT'S EXAMPLES DO NOT MATCH the reference: generate the section again");
            System.exit(same ? 0 : 1);
        }
        System.out.print(generated);
    }

    /** The whole section, as it goes in the prompt. */
    static String section() {
        StringBuilder out = new StringBuilder(SECTION_TITLE + "\n\n");
        out.append("Nos exemplos, o CEP é sempre `").append(ZIP_CODE)
           .append("`, e o cliente está fazendo a primeira compra, a não ser quando o exemplo diz o contrário.\n\n");
        int number = 1;
        for (Example e : EXAMPLES) {
            out.append("**Exemplo ").append(number++).append("**: ").append(describeInput(e)).append('\n');
            out.append("→ ").append(describeOutput(calculate(e))).append("\n\n");
        }
        return out.toString();
    }

    static Result calculate(Example e) {
        Purchase purchase = new Purchase(new Customer("12345678909", "ana@exemplo.com"), e.items(), ZIP_CODE, e.region(),
                e.shippingMethod(), e.coupon(), e.paymentMethod(), e.installments(), e.clubTier());
        TransLog transLog = (zip, grams, service) -> {
            if (e.transLogAnswer() == null) throw new IllegalStateException("este exemplo não devia consultar a TransLog");
            return e.transLogAnswer();
        };
        return Calculator.calculate(purchase, new Context(Catalog.initial(), cpf -> e.customerHasPaidOrder(), transLog));
    }

    static String describeInput(Example e) {
        Catalog catalog = Catalog.initial();
        String items = e.items().stream()
                .map(i -> catalog.find(i.sku()).orElseThrow().name() + " (`" + i.sku() + "`) × " + i.quantity())
                .collect(Collectors.joining(" + "));
        String shipping = "`" + e.shippingMethod() + "`" + switch (e.transLogAnswer()) {
            case null -> "";
            case TransLog.Quote q -> " (a TransLog respondeu `{ \"price_cents\": " + q.priceCents() + ", \"eta_hours\": " + q.etaHours() + " }`)";
            case TransLog.ZipNotServed z -> " (a TransLog respondeu `{ \"error\": \"ZIP_NOT_SERVED\" }`)";
            case TransLog.Unavailable u -> " (a TransLog estava fora do ar)";
        };
        String coupon = e.coupon() == null ? "sem cupom"
                : "cupom `" + e.coupon() + "`" + (e.customerHasPaidOrder() ? " (o cliente já tem um pedido pago)" : "");
        String payment = "`" + e.paymentMethod() + "`" + (e.installments() != null && e.installments() > 1 ? " em " + e.installments() + "×" : "");
        return items + ", " + shipping + ", " + coupon + ", " + payment + ", clube `" + e.clubTier() + "`, região `" + e.region() + "`";
    }

    static String describeOutput(Result result) {
        return switch (result) {
            case Refusal r -> "recusado: `{ \"error\": \"" + r.error() + "\" }`, HTTP " + r.http();
            case Summary s -> "subtotal " + brl(s.productsSubtotal()) + " · cupom " + brl(s.couponDiscount())
                    + " · frete " + brl(s.shippingCost()) + " · prazo " + s.deliveryDays() + " · seguro " + brl(s.insurance())
                    + " · ajuste " + brl(s.paymentAdjustment()) + " · total final " + brl(s.finalTotal())
                    + " · " + s.installments() + "× de " + brl(s.installmentAmount())
                    + " · crédito " + brl(s.nextPurchaseCredit()) + " · brinde " + (s.gift() ? "sim" : "não");
        };
    }

    /** The examples section currently in the prompt (from its title to the next "---" line). */
    static String sectionInPrompt(Path prompt) throws Exception {
        String text = Files.readString(prompt).replace("\r\n", "\n");
        int start = text.indexOf(SECTION_TITLE);
        int end = start < 0 ? -1 : text.indexOf("\n---\n", start);
        return start < 0 || end < 0 ? "" : text.substring(start, end).strip();
    }

    /** 1234.5 -> "1.234,50"; a negative value gets the typographic minus sign, as in V5. */
    static String brl(BigDecimal value) {
        String digits = String.format(Locale.forLanguageTag("pt-BR"), "%,.2f", value.abs());
        return (value.signum() < 0 ? "−" : "") + digits;
    }

    public static List<Item> items(Object... skuAndQuantity) {
        List<Item> list = new java.util.ArrayList<>();
        for (int k = 0; k < skuAndQuantity.length; k += 2) list.add(new Item((String) skuAndQuantity[k], (Integer) skuAndQuantity[k + 1]));
        return list;
    }

    static TransLog.Answer quote(long priceCents, int etaHours) {
        return new TransLog.Quote(priceCents, etaHours);
    }
}
